/// Captures the Simplex quote request instead of hitting the network.
class _CapturingHttp extends HTTP {
  const _CapturingHttp();

  static Uri? lastGet;

  @override
  Future<Response> get({
    required Uri url,
    Map<String, String>? headers,
    required ({InternetAddress host, int port})? proxyInfo,
    Duration? connectionTimeout,
  }) async {
    lastGet = url;
    return Response(utf8.encode('{"error":"stubbed"}'), 200);
  }
}

Widget _app(Widget child) => ProviderScope(
  overrides: [
    coinIconProvider.overrideWithProvider(
      (coin) => Provider((ref) => "assets/svg/bell.svg"),
    ),
  ],
  child: MaterialApp(
    theme: ThemeData(
      extensions: [
        StackColors.fromStackColorTheme(
          StackTheme.fromJson(json: lightThemeJsonMap),
        ),
      ],
    ),
    home: Material(child: SingleChildScrollView(child: child)),
  ),
);

Finder get _amountField =>
    find.byKey(const Key("buyAmountInputFieldTextFieldKey"));

/// The fiat/crypto mode is static state on the form, so put it where the test
/// wants it rather than assuming the default.
Future<void> _useCryptoAmount(WidgetTester tester) async {
  final toggle = find.byWidgetPredicate(
    (w) => w is CustomTextButton && w.text == "Use crypto amount",
  );
  if (toggle.evaluate().isNotEmpty) {
    await tester.tap(toggle, warnIfMissed: false);
    await tester.pump();
  }
  expect(find.text("Enter crypto amount"), findsOneWidget);
}

void main() {
  late Directory hiveDir;

  setUp(() async {
    // Prefs reads the prefs box through DB's own Hive instance; the Simplex
    // quote request needs it open.
    hiveDir = await Directory.systemTemp.createTemp("buy_form_test");
    DB.instance.hive.init(hiveDir.path);
    await DB.instance.hive.openBox<dynamic>(DB.boxNamePrefs);
    await Prefs.instance.init();
  });

  tearDown(() async {
    await DB.instance.hive.close();
    await hiveDir.delete(recursive: true);
  });

  testWidgets("desktop buy form builds its amount field without a coin", (
    tester,
  ) async {
    tester.view.physicalSize = const Size(1600, 3000);
    tester.view.devicePixelRatio = 1.0;
    addTearDown(tester.view.reset);

    await tester.pumpWidget(_app(const BuyForm()));

    expect(
      "${tester.takeException()}",
      isNot(contains("LateInitializationError")),
    );
    expect(_amountField, findsOneWidget);
  });

  testWidgets("mobile buy form builds its amount field with a coin", (
    tester,
  ) async {
    tester.view.physicalSize = const Size(1600, 3000);
    tester.view.devicePixelRatio = 1.0;
    addTearDown(tester.view.reset);

    await tester.pumpWidget(
      _app(BuyForm(coin: Bitcoin(CryptoCurrencyNetwork.main))),
    );

    expect(
      "${tester.takeException()}",
      isNot(contains("LateInitializationError")),
    );
    expect(_amountField, findsOneWidget);
  });

  testWidgets("crypto amount reaches the quote request at full precision", (
    tester,
  ) async {
    SimplexAPI.instance.client = const _CapturingHttp();
    _CapturingHttp.lastGet = null;

    tester.view.physicalSize = const Size(1600, 3000);
    tester.view.devicePixelRatio = 1.0;
    addTearDown(tester.view.reset);

    // Desktop builds the form with no coin; the amount is denominated in the
    // selected crypto, not the wallet's.
    await tester.pumpWidget(_app(const BuyForm()));
    tester.takeException();
    await _useCryptoAmount(tester);

    await tester.enterText(_amountField, "1.23456789");
    await tester.pump();
    expect(
      (tester.widget(_amountField) as TextField).controller!.text,
      "1.23456789",
    );
    expect(find.text("Invalid amount"), findsNothing);

    await tester.enterText(
      find.byKey(const Key("buyViewReceiveAddressFieldKey")),
      "bc1qexampleaddress",
    );
    await tester.pump();

    await tester.tap(find.byType(PrimaryButton));
    await tester.pump();
    await tester.pump();
    tester.takeException();

    expect(_CapturingHttp.lastGet, isNotNull);
    expect(
      _CapturingHttp.lastGet!.queryParameters["REQUESTED_AMOUNT"],
      "1.23456789",
    );
    expect(_CapturingHttp.lastGet!.queryParameters["CRYPTO_TICKER"], "BTC");
  });
}
